MAX_LENGTH = 200


def shorten(line):
    """Cut a Unicode string to the longest text a notification may carry."""
    return line[:MAX_LENGTH]


def message(args):
    """Build a notification, preserving Unicode names and text."""
    body = args.get("text", "")
    who = args.get("mention")
    line = "%s: %s" % (who, body) if who else body
    return shorten(line)
